859	    let size = 0;
860	    let tooLarge = false;
861	    let settled = false;
862	    // A declared Content-Length already tells us the request will exceed the
863	    // limit, but we must still consume the whole request before responding;
864	    // skip buffering from the start to bound memory use while draining.
865	    const declaredLength = Number(req.headers['content-length']);
866	    if (Number.isFinite(declaredLength) && declaredLength > MAX_BODY_BYTES) {
867	      tooLarge = true;
868	    }
869	    req.on('data', (chunk: unknown) => {
870	      if (settled) return;
871	      const buf = Buffer.isBuffer(chunk) ? chunk : Buffer.from(String(chunk));
872	      if (tooLarge) return; // draining the remainder; nothing left to buffer
873	      size += buf.length;
874	      if (size > MAX_BODY_BYTES) {
875	        // Keep reading (and discarding) the rest of the request instead of
876	        // calling req.destroy(): destroying the socket resets the connection
877	        // while the client is still sending, so it would never receive the
